"""Public operation registry shared with the native app. No placeholder operations."""
import json
A=[]
def field(key,label,default='',kind='text'):
 return dict(key=key,label=label,default=str(default),kind=kind)
def add(id,title,families,mode='tools',fields=None,note='',batch=False):
 A.append(dict(id=id,title=title,families=families.split(),mode=mode,fields=fields or [],note=note,batch=batch))
def f(key,label,default='',kind='text'):return field(key,label,default,kind)
rect=[f('x','X da sinistra (px)',0),f('y','Y dall’alto (px)',0),f('width','Larghezza (px)',200),f('height','Altezza (px)',200)]
time=[f('start','Inizio (secondi)',0),f('end','Fine (secondi)',5)]
