for id,title,fields in [('rotate90','Ruota 90°',[]),('rotate270','Ruota −90°',[]),('rotate180','Ruota 180°',[]),('flipH','Rifletti orizzontalmente',[]),('flipV','Rifletti verticalmente',[]),('gray','Bianco e nero',[]),('resize','Ridimensiona',[f('width','Larghezza (px)',1920),f('height','Altezza (0 = proporzioni)',0)]),('crop','Ritaglia',rect),('edit','Regola immagine',[f('brightness','Luminosità (1 = originale)',1),f('contrast','Contrasto',1),f('saturation','Saturazione',1),f('sharpness','Nitidezza',1)]),('redact','Oscura area',rect),('annotate','Aggiungi testo',[f('text','Testo','Nota'),f('x','X (px)',20),f('y','Y (px)',20),f('size','Dimensione testo',32),f('color','Colore HEX','#ff8000')]),('watermark','Filigrana',[f('text','Testo','©'),f('opacity','Opacità 0–1',0.35)]),('tilemark','Filigrana ripetuta',[f('text','Testo','©'),f('opacity','Opacità 0–1',0.2)]),('background','Aggiungi sfondo',[f('color','Colore HEX','#ffffff')]),('removebg','Rimuovi sfondo',[]),('blurbg','Sfoca sfondo',[]),('upscale2','Ingrandisci 2×',[]),('upscale4','Ingrandisci 4×',[]),('palette','Estrai tavolozza',[]),('metadata','Leggi metadati',[]),('editmeta','Modifica metadati',[f('artist','Autore'),f('copyright','Copyright'),f('description','Descrizione')]),('strip','Rimuovi metadati',[]),('compress','Comprimi a una dimensione',[f('mb','Limite (MB)',1)]),('quality90','Comprimi · alta qualità',[]),('quality70','Comprimi · bilanciata',[]),('quality40','Comprimi · minima',[])]:add('image.'+id,title,'image',fields=fields,note='Ingrandimento con interpolazione Lanczos, senza ricostruzione AI.' if id.startswith('upscale') else '')
for id,title in [('ocr','Estrai testo (OCR)'),('qr','Leggi QR e codici a barre'),('faces','Oscura volti'),('textredact','Oscura testo riconosciuto')]:add('vision.'+id,title,'image')
add('image.collage','Crea collage','image',fields=[f('columns','Colonne',2)],batch=True)
add('image.animate','Crea GIF animata','image',fields=[f('duration','Durata fotogramma (ms)',250)],batch=True)
add('image.combine','Unisci immagini in PDF','image',batch=True)
for ext in 'mp4 mov mkv webm avi wmv gif'.split():add('video.to.'+ext,ext.upper(),'video','convert')
for ext in 'mp3 m4a wav flac ogg opus aiff wma'.split():add('audio.to.'+ext,ext.upper(),'audio video','convert')
for id,title,fields in [('trim','Taglia video',time),('split','Dividi video',[f('start','Punto di divisione (s)',5)]),('crop','Ritaglia video',rect),('frames','Estrai fotogrammi',[f('fps','Fotogrammi al secondo',1)]),('redact','Oscura area nel tempo',rect+time),('compress','Comprimi video a MB',[f('mb','Limite (MB)',8)]),('speed','Velocità video',[f('speed','Moltiplicatore',2)]),('rotate','Ruota video 90°',[]),('mute','Rimuovi audio',[]),('strip','Rimuovi metadati video',[]),('addsubs','Aggiungi traccia sottotitoli',[f('file','Sottotitoli SRT/VTT','','file')]),('burnsubs','Incorpora sottotitoli nel video',[f('file','Sottotitoli SRT/VTT','','file')]),('extractsubs','Estrai sottotitoli',[])]:add('video.'+id,title,'video',fields=fields)
add('video.join','Unisci video','video',batch=True,note='L’ordine è quello mostrato nell’elenco dei file.')
for id,title,fields in [('trim','Taglia audio',time),('bleep','Oscura audio con un tono',time),('fade','Dissolvenze',[f('fade','Durata dissolvenza (s)',1)]),('normalize','Normalizza volume',[]),('denoise','Riduci rumore',[]),('speed','Velocità audio',[f('speed','Moltiplicatore',1.5)]),('pitch','Cambia tonalità',[f('semitones','Semitoni',2)]),('mono','Converti in mono',[]),('stereo','Converti in stereo',[]),('tags','Modifica tag',[f('title','Titolo'),f('artist','Artista'),f('album','Album')]),('artwork','Aggiungi copertina',[f('file','Immagine copertina','','file')]),('strip','Rimuovi metadati audio',[])]:add('audio.'+id,title,'audio',fields=fields)
add('audio.compress','Comprimi audio · AAC 128 kbps','audio')
