add('audio.volume','Canali e volume','audio',fields=[f('volume','Moltiplicatore volume',1),f('channels','Canali (1 mono / 2 stereo)',2)])
add('audio.waveform','Crea video della forma d’onda','audio')
add('audio.join','Unisci audio','audio',batch=True)
for ext in 'txt srt vtt'.split():add('transcribe.'+ext,'Trascrivi → '+ext.upper(),'audio video',note='Whisper tiny multilingue, locale. La trascrizione automatica può contenere errori.')
