for ext in 'png jpg txt md docx xlsx pptx epub'.split():add('pdf.to.'+ext,ext.upper(),'pdf','convert',note='DOCX/EPUB: testo riadattabile; XLSX: tabelle rilevate; PPTX: una pagina come immagine per diapositiva. Il layout complesso può cambiare.')
for id,title,fields in [('merge','Unisci PDF',[]),('split','Separa tutte le pagine',[]),('select','Estrai/riordina pagine',[f('pages','Pagine, es. 3,1,2 oppure 1-5','1')]),('rotate','Ruota pagine 90°',[]),('reverse','Inverti pagine',[]),('numbers','Numera pagine',[f('start','Numero iniziale',1)]),('password','Proteggi PDF',[f('password','Password','','password')]),('unlock','Sblocca PDF',[f('password','Password attuale','','password')]),('compress','Comprimi PDF',[f('dpi','Risoluzione immagini (dpi)',120)]),('gray','PDF in scala di grigi',[]),('watermark','Filigrana PDF',[f('text','Testo','BOZZA')]),('images','Estrai immagini',[]),('metadata','Leggi metadati PDF',[]),('strip','Rimuovi metadati PDF',[]),('editmeta','Modifica metadati PDF',[f('title','Titolo'),f('author','Autore'),f('subject','Oggetto')]),('redact','Oscura testo nel PDF',[f('text','Testo da eliminare')]),('addtext','Aggiungi testo al PDF',[f('text','Testo'),f('page','Pagina',1),f('x','X (punti)',50),f('y','Y (punti)',50),f('size','Dimensione',14)]),('sign','Firma PDF con immagine',[f('file','Firma PNG trasparente','','file'),f('page','Pagina',1)]+rect),('fill','Compila campi PDF',[f('values','Campi e valori JSON','{}')]),('forms','Elenca campi modulo',[])]:add('pdf.'+id,title,'pdf',fields=fields,batch=id=='merge',note='Ricrea le pagine come immagini: testo ricercabile, moduli e firme digitali non vengono conservati.' if id in ['compress','gray'] else '')
add('pdf.ocr','Rendi PDF ricercabile (OCR)','pdf',note='Riconoscimento locale Vision; aggiunge uno strato di testo invisibile.')
for ext in 'pdf docx odt rtf html md txt epub'.split():add('document.to.'+ext,ext.upper(),'document','convert')
for ext in 'pdf pptx odp png jpg'.split():add('slides.to.'+ext,ext.upper(),'slides','convert')
for ext in 'csv tsv xlsx ods json pdf'.split():add('sheet.to.'+ext,ext.upper(),'sheet','convert',note='CSV/TSV/JSON: primo foglio, valori; non conservano formule o impaginazione.')
for ext in 'srt vtt'.split():add('subtitle.to.'+ext,ext.upper(),'subtitle','convert')
add('subtitle.shift','Sposta tempi sottotitoli','subtitle',fields=[f('seconds','Spostamento (s)',1)])
for ext in 'zip tar tar.gz'.split():add('archive.'+ext,'Comprimi → '+ext.upper(),'any','actions',batch=True)
add('archive.password','ZIP con password AES','any','actions',fields=[f('password','Password','','password')],batch=True)
add('archive.extract','Estrai archivio','archive','convert',fields=[f('password','Password ZIP/7z (facoltativa)','','password')])
add('files.strip','Rimuovi metadati','image video audio pdf document','tools',note='Crea una copia senza metadati supportati. Contenuti visibili e dati incorporati nel documento possono restare.')
add('files.hash','Calcola SHA-256','any','actions')
add('files.renameOriginals','Rinomina file in serie','any','actions',fields=[f('prefix','Prefisso','File'),f('start','Numero iniziale',1)],batch=True,note='Questa azione cambia il nome dei file originali. Non sovrascrive file esistenti.')
add('native.hash','Copia checksum SHA-256','any','actions')
