for id,title in [('copy','Copia file'),('path','Copia percorsi'),('reveal','Mostra nel Finder'),('move','Sposta in…'),('copyto','Copia in…'),('airdrop','AirDrop'),('float','Conserva nello scaffale'),('terminal','Apri Terminale qui'),('copyimage','Copia immagine')]:add('native.'+id,title,'image' if id=='copyimage' else 'any','actions')
